package com.smartmart.recommendation.service;
import com.smartmart.common.exception.BusinessException; import com.smartmart.inventory.repository.InventoryRepository; import com.smartmart.order.entity.CustomerOrder; import com.smartmart.order.repository.CustomerOrderRepository; import com.smartmart.product.dto.ProductResponse; import com.smartmart.product.entity.Product; import com.smartmart.product.repository.ProductRepository; import com.smartmart.user.entity.User; import com.smartmart.wishlist.repository.WishlistRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.util.*; import java.util.stream.Collectors;
/** Transparent rule-based ranking: order co-occurrence, category affinity, wishlist, active offers, live availability. */
@Service @RequiredArgsConstructor public class RecommendationService { private final ProductRepository products; private final CustomerOrderRepository orders; private final WishlistRepository wishlist; private final InventoryRepository inventory;
 @Transactional(readOnly=true) public List<ProductResponse> forUser(User u){List<CustomerOrder> mine=orders.findByUserIdOrderByCreatedAtDesc(u.getId());Set<Long>bought=mine.stream().flatMap(o->o.getItems().stream()).map(i->i.getProduct().getId()).collect(Collectors.toSet());Set<Long>wished=wishlist.findByUserIdOrderByCreatedAtDesc(u.getId()).stream().map(w->w.getProduct().getId()).collect(Collectors.toSet());Map<String,Long>cats=mine.stream().flatMap(o->o.getItems().stream()).collect(Collectors.groupingBy(i->i.getProduct().getCategory(),Collectors.counting()));wishlist.findByUserIdOrderByCreatedAtDesc(u.getId()).forEach(w->cats.merge(w.getProduct().getCategory(),2L,Long::sum));Map<Long,Integer> co=pairs(bought);return products.findAll().stream().filter(p->!bought.contains(p.getId())&&available(p)).sorted(Comparator.comparingInt((Product p)->score(p,wished,cats,co)).reversed().thenComparing(Product::getName)).limit(8).map(this::map).toList();}
 @Transactional(readOnly=true) public List<ProductResponse> related(Long id){Product base=products.findById(id).orElseThrow(()->BusinessException.notFound("Product not found"));Map<Long,Integer>co=pairs(Set.of(id));return products.findAll().stream().filter(p->!p.getId().equals(id)&&available(p)).sorted(Comparator.comparingInt((Product p)->co.getOrDefault(p.getId(),0)).reversed().thenComparing(p->p.getCategory().equalsIgnoreCase(base.getCategory())?0:1)).limit(8).map(this::map).toList();}
 private Map<Long,Integer>pairs(Set<Long> anchors){Map<Long,Integer>r=new HashMap<>();for(CustomerOrder o:orders.findAllWithItems()){Set<Long>ids=o.getItems().stream().map(i->i.getProduct().getId()).collect(Collectors.toSet());if(ids.stream().anyMatch(anchors::contains))ids.stream().filter(x->!anchors.contains(x)).forEach(x->r.merge(x,1,Integer::sum));}return r;}
 private int score(Product p,Set<Long>wished,Map<String,Long>cats,Map<Long,Integer>co){var i=inventory.findByProductId(p.getId()).orElse(null);int s=(int)(cats.getOrDefault(p.getCategory(),0L)*10)+co.getOrDefault(p.getId(),0)*20;if(wished.contains(p.getId()))s+=100;if(i!=null&&i.getDiscountPercentage()!=null&&i.getDiscountPercentage().signum()>0)s+=8;return s;}
 private boolean available(Product p){return inventory.findByProductId(p.getId()).map(i->i.getQuantity()>0).orElse(false);} private ProductResponse map(Product p){var i=inventory.findByProductId(p.getId()).orElse(null);return ProductResponse.builder().id(p.getId()).name(p.getName()).brand(p.getBrand()).category(p.getCategory()).price(p.getPrice()).aisle(p.getAisle()).shelf(p.getShelf()).description(p.getDescription()).createdAt(p.getCreatedAt()).availableQuantity(i==null?0:i.getQuantity()).discountPercentage(i==null?BigDecimal.ZERO:Optional.ofNullable(i.getDiscountPercentage()).orElse(BigDecimal.ZERO)).build();}}
